CREATE TABLE IF NOT EXISTS gst_return_sections(section_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, section_code TEXT NOT NULL, supply_class TEXT NOT NULL, taxable_value NUMERIC NOT NULL DEFAULT 0, tax_value NUMERIC NOT NULL DEFAULT 0, amendment_value NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'DRAFT', created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(filing_id,section_code,supply_class));
CREATE TABLE IF NOT EXISTS gst_tax_payments(payment_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, payment_date DATE, challan_no TEXT, amount NUMERIC NOT NULL DEFAULT 0, interest NUMERIC NOT NULL DEFAULT 0, penalty NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'DRAFT', created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(filing_id,challan_no));
CREATE TABLE IF NOT EXISTS gst_filing_acknowledgements(acknowledgement_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, filing_reference TEXT NOT NULL, acknowledgement_no TEXT, filed_at TIMESTAMP, status TEXT NOT NULL DEFAULT 'RECEIVED', notes TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(filing_id,filing_reference));
CREATE TABLE IF NOT EXISTS gst_filing_signoffs(signoff_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', signed_by TEXT, signed_at TIMESTAMP, remarks TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(filing_id));
